INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist Qualitätssicherung nur für große Projekte nötig?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kleine Projekte profitieren"}, {"text": "Ja", "correct": false, "because": "Qualität immer relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit Qualitätssicherung?', 3, '[{"text": "Standards einhalten", "correct": true, "because": "Konsistenz und Zuverlässigkeit"}, {"text": "Schnellere Entwicklung", "correct": false, "because": "Nicht primär"}, {"text": "Mehr Features", "correct": false, "because": "Kein Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methoden gehören zur Qualitätssicherung?', 5, '[{"text": "Code-Reviews", "correct": true, "because": "Findet Fehler früh"}, {"text": "Tests", "correct": true, "because": "Sichert Funktionalität"}, {"text": "Mehr Entwickler", "correct": false, "because": "Kein direkter Faktor"}, {"text": "Schnelle Releases", "correct": false, "because": "Qualität vor Tempo"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Qualitätssicherung erhöht Zuverlässigkeit. b) Sie verzögert immer Projekte.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Verzögerung nicht zwangsläufig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Qualitätssicherung?', 4, '[{"text": "Standards", "correct": false, "because": "Kern der QS"}, {"text": "Best Practices", "correct": false, "because": "Fördern Qualität"}, {"text": "Farbschema", "correct": true, "because": "Kein QS-Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Qualitätssicherung ohne Tests möglich ist?', 2, '[{"text": "Ja", "correct": true, "because": "Reviews allein reichen"}, {"text": "Nein", "correct": false, "because": "Tests üblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Werkzeug nutze ich für Qualitätssicherung?', 3, '[{"text": "Linting-Tools", "correct": true, "because": "Prüft Code-Standards"}, {"text": "Debugger", "correct": false, "because": "Fehlerfokussiert"}, {"text": "UI-Designer", "correct": false, "because": "Design-spezifisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte sind bei Qualitätssicherung entscheidend?', 5, '[{"text": "Konsistenz", "correct": true, "because": "Einheitliche Standards"}, {"text": "Fehlererkennung", "correct": true, "because": "Sichert Zuverlässigkeit"}, {"text": "Schnelle Deployment", "correct": false, "because": "Nicht primär"}, {"text": "Viele Features", "correct": false, "because": "Qualität vor Quantität"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Qualitätssicherung spart langfristig Zeit. b) Sie macht Projekte teurer. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kosten nicht zwangsläufig höher"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für Qualitätssicherung?', 4, '[{"text": "Testpläne", "correct": false, "because": "Strukturieren QS"}, {"text": "Code-Reviews", "correct": false, "because": "Sichern Standards"}, {"text": "Hübsche UI", "correct": true, "because": "Kein QS-Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Qualitätssicherung ohne Standards möglich?', 2, '[{"text": "Nein", "correct": true, "because": "Standards sind Basis"}, {"text": "Ja", "correct": false, "because": "Unstrukturiert ineffizient"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet Qualitätssicherung?', 4, '[{"text": "Weniger Fehler", "correct": true, "because": "Früh erkannt"}, {"text": "Höhere Zufriedenheit", "correct": true, "because": "Zuverlässiges Produkt"}, {"text": "Schnellere Releases", "correct": false, "because": "Qualität vor Tempo"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Qualitätssicherung nur für Kunden ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Team profitiert"}, {"text": "Ja", "correct": false, "because": "Interner Nutzen"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Qualitätssicherung?', 3, '[{"text": "Standards einhalten", "correct": true, "because": "Sichert Konsistenz"}, {"text": "Schnelle Umsetzung", "correct": false, "because": "Qualität zählt"}, {"text": "Viele Features", "correct": false, "because": "Qualität vor Quantität"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Qualitätssicherung nutzt Best Practices. b) Sie garantiert fehlerfreien Code.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Fehlerfreiheit nicht garantiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Probleme löst Qualitätssicherung?', 5, '[{"text": "Fehlende Standards", "correct": true, "because": "Einheitlichkeit schaffen"}, {"text": "Hoher Nachbesserungsaufwand", "correct": true, "because": "Frühe Fehlererkennung"}, {"text": "Langsame Server", "correct": false, "because": "Technischer Fokus"}, {"text": "UI-Fehler", "correct": false, "because": "Teilweise, nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei Qualitätssicherung unwichtig?', 3, '[{"text": "Tests", "correct": false, "because": "Sichern Qualität"}, {"text": "Reviews", "correct": false, "because": "Fördern Standards"}, {"text": "Schriftart", "correct": true, "because": "Kein QS-Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Erhöht Qualitätssicherung den Aufwand?', 3, '[{"text": "Ja", "correct": true, "because": "Kurzfristig mehr Arbeit"}, {"text": "Nein", "correct": false, "because": "Langfristig effizienter"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Qualitätssicherung Kundenzufriedenheit steigert?', 2, '[{"text": "Ja", "correct": true, "because": "Zuverlässiges Produkt"}, {"text": "Nein", "correct": false, "because": "Klarer Nutzen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist bei Qualitätssicherung zentral?', 4, '[{"text": "Testautomatisierung", "correct": true, "because": "Effiziente Prüfung"}, {"text": "Manuelle Änderungen", "correct": false, "because": "Ineffizient"}, {"text": "UI-Animationen", "correct": false, "because": "Kein QS-Fokus"}]');